const CACHE_NAME="flights-finder-v2",STATIC_ASSETS=["/","/static/style.css","/static/app.min.js","/static/icons/icon-192.png","/static/icons/icon-512.png"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(STATIC_ASSETS))),self.skipWaiting()}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.filter(e=>e!==CACHE_NAME).map(e=>caches.delete(e))))),self.clients.claim()}),self.addEventListener("fetch",e=>{new URL(e.request.url).pathname.startsWith("/api/")?e.respondWith(fetch(e.request).catch(()=>new Response(JSON.stringify({error:"You are offline. Please check your connection."}),{status:503,headers:{"Content-Type":"application/json"}}))):e.respondWith(caches.match(e.request).then(t=>t?(fetch(e.request).then(t=>{t&&200===t.status&&caches.open(CACHE_NAME).then(s=>{s.put(e.request,t)})}).catch(()=>{}),t):fetch(e.request).then(t=>{if(t&&200===t.status){const s=t.clone();caches.open(CACHE_NAME).then(t=>{t.put(e.request,s)})}return t})))});